import { describe, expect, test } from "vitest";

import {
  authMethodClientsSource,
  generateIslandsRendererEntrySource,
} from "./auth-method-clients-codegen.js";

const ENTRY_DIR = "/app/.plumix";

const UNCHANGED =
  '// Generated by plumix — do not edit.\nexport * from "plumix/blocks/island-renderer";\n';

const method = (client?: string) => ({
  ...(client === undefined ? {} : { client }),
});

describe("generateIslandsRendererEntrySource", () => {
  test("with no method clients, the entry is unchanged", () => {
    expect(
      generateIslandsRendererEntrySource(ENTRY_DIR, [
        { authMethods: [method()] },
        {},
      ]),
    ).toBe(UNCHANGED);
  });

  test("imports each method client once, in plugin order, and registers them before its re-export", () => {
    const source = generateIslandsRendererEntrySource(ENTRY_DIR, [
      { authMethods: [method("@acme/plumix-otp/client"), method()] },
      {
        authMethods: [
          method("/app/plugins/fixture/client.ts"),
          method("@acme/plumix-otp/client"),
        ],
      },
    ]);

    expect(source).toBe(
      "// Generated by plumix — do not edit.\n" +
        'import c0 from "@acme/plumix-otp/client";\n' +
        'import c1 from "../plugins/fixture/client.ts";\n' +
        'import { registerAuthMethodClients } from "plumix/auth/client";\n' +
        "registerAuthMethodClients([c0, c1]);\n" +
        'export * from "plumix/blocks/island-renderer";\n',
    );
  });
});

describe("authMethodClientsSource", () => {
  test("is empty when no method declares a client", () => {
    expect(authMethodClientsSource(ENTRY_DIR, [{ authMethods: [] }])).toBe("");
  });
});
